import Foundation

extension JSONDecoder {
    /// Decoder for every TMDB response. Converts snake_case keys to camelCase.
    static var tmdb: JSONDecoder {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return decoder
    }
}

enum TMDBDate {
    private static let calendar: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC")!
        return calendar
    }()

    /// Parses `"yyyy-MM-dd"`. Returns nil for empty or malformed input.
    static func parse(_ string: String) -> Date? {
        let parts = string.split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 3,
              parts[0].count == 4, parts[1].count == 2, parts[2].count == 2,
              let year = Int(parts[0]), let month = Int(parts[1]), let day = Int(parts[2])
        else { return nil }
        let components = DateComponents(year: year, month: month, day: day)
        guard let date = calendar.date(from: components),
              calendar.dateComponents([.year, .month, .day], from: date) == components
        else { return nil }
        return date
    }

    static func year(of date: Date?) -> String? {
        guard let date else { return nil }
        return String(calendar.component(.year, from: date))
    }
}

extension KeyedDecodingContainer {
    /// Decodes a TMDB date: missing, null, or empty string gives nil.
    func decodeTMDBDate(forKey key: Key) throws -> Date? {
        guard let string = try decodeIfPresent(String.self, forKey: key), !string.isEmpty else {
            return nil
        }
        guard let date = TMDBDate.parse(string) else {
            throw DecodingError.dataCorruptedError(
                forKey: key, in: self, debugDescription: "Expected yyyy-MM-dd, got \(string)")
        }
        return date
    }
}
